//! Synthetic Python reference fixtures are shared, not regenerated by Rust.
use disk_archive_core::redaction::{FindingRaw, Limits, PlanBuilder};
use serde::Deserialize;

#[derive(Deserialize)]
struct Inputs {
    cases: Vec<Case>,
}
#[derive(Deserialize)]
struct Case {
    id: String,
    input_hex: String,
    findings: Vec<Finding>,
    drop_lines: Vec<u64>,
}
#[derive(Deserialize)]
struct Finding {
    detector: String,
    raw: String,
    raw_v2: String,
}
#[derive(Deserialize)]
struct Outputs {
    cases: Vec<Expected>,
}
#[derive(Deserialize)]
struct Expected {
    id: String,
    output_hex: String,
    replacements: u64,
}

fn hex(s: &str) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    if !s.len().is_multiple_of(2) {
        return Err("odd hex length".into());
    }
    s.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| Ok(u8::from_str_radix(std::str::from_utf8(pair)?, 16)?))
        .collect()
}

#[test]
fn golden_parity() -> Result<(), Box<dyn std::error::Error>> {
    let inputs: Inputs = serde_json::from_str(include_str!(
        "../../../legacy/python/fixtures/redactor/cases.json"
    ))?;
    let expected: Outputs = serde_json::from_str(include_str!(
        "../../../legacy/python/fixtures/redactor/expected.json"
    ))?;
    assert_eq!(inputs.cases.len(), expected.cases.len());
    assert_eq!(inputs.cases.len(), 16);
    for (case, expected) in inputs.cases.into_iter().zip(expected.cases) {
        assert_eq!(case.id, expected.id);
        let mut builder = PlanBuilder::new(Limits::default()).map_err(|_| "limits")?;
        for finding in &case.findings {
            for raw in [&finding.raw, &finding.raw_v2] {
                builder
                    .push(&FindingRaw {
                        label: &finding.detector,
                        raw,
                    })
                    .map_err(|_| "finding")?;
            }
        }
        let plan = builder.finish(case.drop_lines).map_err(|_| "plan")?;
        let mut output = Vec::new();
        let report = plan
            .redact(hex(&case.input_hex)?.as_slice(), &mut output)
            .map_err(|_| "redact")?;
        assert_eq!(output, hex(&expected.output_hex)?, "{}", case.id);
        assert_eq!(report.replacements, expected.replacements, "{}", case.id);
        assert_eq!(report.guarded_lines, 0, "{}", case.id);
    }
    Ok(())
}
